    hlc_ms = CASE WHEN CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) > hlc_ms THEN CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHEN hlc_counter >= 999999 THEN hlc_ms + 1 ELSE hlc_ms END,
    seq = seq + 1
  WHERE id = 1;
